#include "parable_libra.h"
#include "lab_wav.h"
#include "soundforge/analysis.h"
#include <chrono>
#include <iomanip>
#include <iostream>
using parable::dsp::Libra;using parable::dsp::LibraControls;
int main(int argc,char** argv){try{
    lab::require(argc==5&&std::string(argv[1])=="--input"&&std::string(argv[3])=="--output","Use --input monoPCM16.wav --output NEW_DIR");const std::filesystem::path source=argv[2],out=argv[4];lab::require(!std::filesystem::exists(out),"Output directory must be new");auto wave=lab::read(source);lab::require(wave.samples.size()>=wave.rate,"Need at least1second input");wave.samples.resize(std::min(wave.samples.size(),std::size_t(8)*wave.rate));const auto original=soundforge::stats(wave.samples);lab::require(original.peak>0,"Silent input rejected");const double inputGain=.04/original.peak;for(auto& x:wave.samples)x=float(x*inputGain);wave.samples.resize(wave.samples.size()+wave.rate,0);
    std::filesystem::create_directories(out);std::ofstream csv(out/"renders.csv"),bias(out/"bias.csv"),trace(out/"state.csv");for(auto* f:{&csv,&bias,&trace}){lab::require(bool(*f),"Cannot open receipt");*f<<std::setprecision(15);}
    csv<<"file,drive,level,RB1_drift,frames,offline_gain,raw_rms,raw_peak,final_rms,final_peak,dc,failures,input_clamps,rail_samples,host_us_per_frame\n";bias<<"drive,RB1_drift,driver_V,combined_V,upper_A,lower_A\n";trace<<"drive,RB1_drift,frame,driver_V,combined_V,upper_A,lower_A,error_V,pole_residual_V,jack_V,railed\n";
    auto write=[&](const std::string& name,const std::vector<float>& x,double gain,LibraControls c,double us,uint32_t rails){auto y=x;for(auto& v:y)v=float(v*gain);const auto a=soundforge::stats(x),b=soundforge::stats(y);lab::require(b.peak<.999,"Refuse clipped WAV");lab::write(out/name,{wave.rate,y});csv<<name<<','<<c.drive<<','<<c.level<<','<<c.damagedBias<<','<<y.size()<<','<<gain<<','<<a.rms<<','<<a.peak<<','<<b.rms<<','<<b.peak<<','<<b.mean<<",0,0,"<<rails<<','<<us<<'\n';};
    auto dry=wave.samples;for(auto& x:dry)x/=4;write("00_dry_common.wav",dry,1,{0,1,false},0,0);
    for(unsigned group=0;group<2;++group){LibraControls c;c.drive=group?.65f:.1f;std::array<std::vector<float>,2> signals;double costs[2]{};uint32_t rails[2]{};
        for(unsigned fault=0;fault<2;++fault){c.damagedBias=fault!=0;Libra model;lab::require(model.prepare(float(wave.rate),c),"Libra prepare failed");const auto p=model.bias();bias<<c.drive<<','<<fault<<','<<p.driverVolts<<','<<p.combinedVolts<<','<<p.upperAmps<<','<<p.lowerAmps<<'\n';auto& y=signals[fault];y.resize(wave.samples.size());
            for(std::size_t n=0;n<y.size();++n){y[n]=model.process(wave.samples[n]);if(n%8192==0){const auto v=model.probe();trace<<c.drive<<','<<fault<<','<<n<<','<<v.driverVolts<<','<<v.combinedVolts<<','<<v.upperAmps<<','<<v.lowerAmps<<','<<v.errorVolts<<','<<v.poleResidualVolts<<','<<v.jackVolts<<','<<v.railed<<'\n';}}
            lab::require(!model.failures()&&!model.invalidInputs()&&!model.inputClamps(),"Containment in ordinary audio");rails[fault]=model.railSamples();model.reset();std::vector<float> repeat(y.size());const auto begin=std::chrono::steady_clock::now();for(std::size_t n=0;n<y.size();++n)repeat[n]=model.process(wave.samples[n]);costs[fault]=std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-begin).count()/y.size();lab::require(repeat==y&&!model.failures()&&model.railSamples()==rails[fault],"Reset/repeat mismatch");const std::string name=std::string(group?"high":"low")+(fault?"_RB1_270k_raw.wav":"_healthy_raw.wav");write(name,y,1,c,costs[fault],rails[fault]);std::cout<<"Wrote "<<name<<" RMS="<<soundforge::stats(y).rms<<" host_us/frame="<<costs[fault]<<'\n'<<std::flush;
        }
        const double target=std::min({soundforge::rmsTarget(signals,.07,.89),16*soundforge::stats(signals[0]).rms,16*soundforge::stats(signals[1]).rms});for(unsigned fault=0;fault<2;++fault){c.damagedBias=fault!=0;write(std::string(group?"high":"low")+(fault?"_RB1_270k_matched.wav":"_healthy_matched.wav"),signals[fault],soundforge::rmsGain(soundforge::stats(signals[fault]),target),c,costs[fault],rails[fault]);}
    }
    std::ofstream settings(out/"settings.json"),listen(out/"LISTEN.txt");settings<<std::setprecision(15)<<"{\"source\":\"published recipe: Guitar-TECHS Player3 take03\",\"excerpt_seconds_max\":8,\"tail_seconds\":1,\"input_peak_model_V\":0.04,\"input_gain\":"<<inputGain<<",\"low_drive\":0.1,\"high_drive\":0.65,\"level\":0.8,\"RB1_healthy_ohms\":27000,\"RB1_fault_ohms\":270000,\"output_volts_per_unit\":4,\"factor\":4,\"FIR_taps\":97,\"gain_A\":40,\"gain_pole_Hz\":500,\"feedback_ratio\":0.25,\"stage_load_ohms\":1000,\"V_BE_V\":0.64,\"transistor_beta\":100,\"state_bytes\":"<<sizeof(Libra)<<"}\n";
    listen<<"SF013 OptionB reduced class-AB feedback guitar amplifier. One shared dry plus low/high healthy/R_B1-drift raw and RMS matched. Same input/Level. R_B1 alone27k->270k changes real bias/conduction. Four exact affine conduction regions close the gain-stage feedback at each internal step; no added notch/dropout/filter fault. Physical driver rail events are normal overdrive, not PCM clipping. Raw jackV/4; offline matching gains explicit, not LUFS. Fixed V_BE/beta/resistive bias are declared approximations; not a hardware design, thermal model or commercial-amp clone. Founder listening and real Daisy timing unproven.\n";
    for(auto* f:{&csv,&bias,&trace,&settings,&listen}){f->flush();lab::require(bool(*f),"Cannot finish receipt");}return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
